// left[i]: steps to previous element STRICTLY smaller
// right[i]: steps to next element smaller-or-EQUAL (asymmetry!)
long long sumSubarrayMins(vector<int>& a) {
    int n = a.size(); long long ans = 0; const ll MOD = 1e9+7;
    vector<int> L(n), R(n);
    stack<int> st;
    for (int i = 0; i < n; i++) {
        while (!st.empty() && a[st.top()] >= a[i]) st.pop();   // ≥ pops: STRICT left
        L[i] = st.empty() ? -1 : st.top();
        st.push(i);
    }
    while (!st.empty()) st.pop();
    for (int i = n - 1; i >= 0; i--) {
        while (!st.empty() && a[st.top()] > a[i]) st.pop();    // > pops: NON-STRICT right
        R[i] = st.empty() ? n : st.top();
        st.push(i);
    }
    for (int i = 0; i < n; i++)
        ans = (ans + (long long)(i - L[i]) * (R[i] - i) % MOD * a[i]) % MOD;
    return ans;
}

