const long long MOD = 1000000007LL;

int sumSubarrayMins(const vector<int>& a) {
    int n = (int)a.size();
    vector<long long> left(n), right(n);
    stack<int> st;

    // left[i] = how many subarrays end at i where a[i] is the minimum.
    // STRICT on the left: pop while a[top] >= a[i].
    for (int i = 0; i < n; ++i) {
        while (!st.empty() && a[st.top()] >= a[i]) st.pop();
        left[i] = st.empty() ? i + 1 : i - st.top();
        st.push(i);
    }
    while (!st.empty()) st.pop();

    // right[i] = how many start at i. NON-STRICT: pop only while a[top] > a[i].
    for (int i = n - 1; i >= 0; --i) {
        while (!st.empty() && a[st.top()] > a[i]) st.pop();
        right[i] = st.empty() ? n - i : st.top() - i;
        st.push(i);
    }

    long long total = 0;
    for (int i = 0; i < n; ++i)
        total = (total + a[i] % MOD * (left[i] % MOD) % MOD * (right[i] % MOD)) % MOD;
    return (int)total;
}

// POLICY: equal prices MERGE into the span. Popping while price[top] <= today
// means a run of equal prices is absorbed, so [10,10,10] gives spans 1,2,3.
// The strict alternative (pop while <) would give 1,1,1 -- also defensible,
// but the merged reading matches the classic GFG definition.
vector<int> stockSpan(const vector<int>& price) {
    int n = (int)price.size();
    vector<int> span(n, 1);
    stack<int> st;                                   // indices, decreasing price
    for (int i = 0; i < n; ++i) {
        while (!st.empty() && price[st.top()] <= price[i]) st.pop();
        span[i] = st.empty() ? i + 1 : i - st.top(); // DISTANCE to the blocker
        st.push(i);
    }
    return span;
}

class QueueWithMin {
    // each entry carries the minimum of everything at or below it in ITS stack
    vector<pair<int,int>> in, out;      // (value, min-in-this-stack)

    static void pushPair(vector<pair<int,int>>& st, int v) {
        int mn = st.empty() ? v : min(v, st.back().second);
        st.push_back({v, mn});
    }
    void flip() {                        // ONLY when out is empty
        while (!in.empty()) { pushPair(out, in.back().first); in.pop_back(); }
    }
public:
    void push(int v) { pushPair(in, v); }
    bool pop(int& out_v) {
        if (out.empty()) flip();
        if (out.empty()) return false;
        out_v = out.back().first; out.pop_back();
        return true;
    }
    bool getMin(int& out_v) const {
        if (in.empty() && out.empty()) return false;
        if (in.empty())       out_v = out.back().second;
        else if (out.empty()) out_v = in.back().second;
        else                  out_v = min(in.back().second, out.back().second);
        return true;
    }
    bool empty() const { return in.empty() && out.empty(); }
};

