class QueueWithMin:
    """Two min-stacks with the same flip-on-empty law as LC232."""

    def __init__(self):
        self._in = []     # (value, min-in-this-stack)
        self._out = []

    @staticmethod
    def _push_pair(st, v):
        mn = v if not st else min(v, st[-1][1])
        st.append((v, mn))

    def _flip(self):
        """ONLY when out is empty."""
        while self._in:
            QueueWithMin._push_pair(self._out, self._in.pop()[0])

    def push(self, v: int) -> None:
        QueueWithMin._push_pair(self._in, v)

    def pop(self):
        if not self._out:
            self._flip()
        return self._out.pop()[0] if self._out else None

    def get_min(self):
        if not self._in and not self._out:
            return None
        if not self._in:
            return self._out[-1][1]
        if not self._out:
            return self._in[-1][1]
        return min(self._in[-1][1], self._out[-1][1])

    def empty(self) -> bool:
        return not self._in and not self._out

