// bal[i] = balance over the first i characters. A substring [l, r] is a correct
// bracket sequence iff BOTH:
//   (1) bal[r+1] == bal[l]                      -- it closes everything it opens
//   (2) min(bal[l..r+1]) >= bal[l]              -- it never dips below its start
struct BracketQueries {
    vector<int> bal;
    vector<vector<int>> sparse;
    vector<int> logTable;

    explicit BracketQueries(const string& s) {
        int n = (int)s.size();
        bal.assign(n + 1, 0);
        for (int i = 0; i < n; ++i) bal[i + 1] = bal[i] + (s[i] == '(' ? 1 : -1);

        int m = n + 1;
        logTable.assign(m + 1, 0);
        for (int i = 2; i <= m; ++i) logTable[i] = logTable[i / 2] + 1;
        int K = logTable[m] + 1;
        sparse.assign(K, vector<int>(m));
        sparse[0] = bal;
        for (int k = 1; k < K; ++k)
            for (int i = 0; i + (1 << k) <= m; ++i)
                sparse[k][i] = min(sparse[k-1][i], sparse[k-1][i + (1 << (k-1))]);
    }
    int rangeMin(int l, int r) const {          // inclusive over bal indices
        int k = logTable[r - l + 1];
        return min(sparse[k][l], sparse[k][r - (1 << k) + 1]);
    }
    bool isCorrect(int l, int r) const {        // substring indices, inclusive
        if (((r - l + 1) & 1) != 0) return false;        // odd length: impossible
        if (bal[r + 1] != bal[l]) return false;          // condition (1)
        return rangeMin(l, r + 1) >= bal[l];             // condition (2)
    }
};

