class BracketQueries:
    """bal[i] = balance over the first i characters. A substring [l, r] is a
    correct bracket sequence iff BOTH:
      (1) bal[r+1] == bal[l]            -- it closes everything it opens
      (2) min(bal[l..r+1]) >= bal[l]    -- it never dips below its start"""

    def __init__(self, s: str):
        n = len(s)
        self.bal = [0] * (n + 1)
        for i, c in enumerate(s):
            self.bal[i + 1] = self.bal[i] + (1 if c == "(" else -1)

        m = n + 1
        self.log = [0] * (m + 1)
        for i in range(2, m + 1):
            self.log[i] = self.log[i // 2] + 1
        K = self.log[m] + 1
        self.sparse = [self.bal[:]]
        for k in range(1, K):
            prev = self.sparse[k - 1]
            step = 1 << (k - 1)
            self.sparse.append([min(prev[i], prev[i + step])
                                for i in range(m - (1 << k) + 1)])

    def range_min(self, l: int, r: int) -> int:
        """Inclusive over bal indices."""
        k = self.log[r - l + 1]
        return min(self.sparse[k][l], self.sparse[k][r - (1 << k) + 1])

    def is_correct(self, l: int, r: int) -> bool:
        """Substring indices, inclusive."""
        if (r - l + 1) % 2:
            return False                       # odd length: impossible
        if self.bal[r + 1] != self.bal[l]:
            return False                       # condition (1)
        return self.range_min(l, r + 1) >= self.bal[l]   # condition (2)

