// GRAMMAR:
//   expr   := term   (('+' | '-') term)*
//   term   := factor (('*' | '/') factor)*
//   factor := number | '(' expr ')' | '-' factor      <- unary minus lives HERE
struct Calculator {
    string s;
    size_t i = 0;

    explicit Calculator(string src) : s(move(src)) {}

    void skip() { while (i < s.size() && s[i] == ' ') ++i; }

    long long factor() {
        skip();
        if (s[i] == '-') { ++i; return -factor(); }     // unary minus, right-recursive
        if (s[i] == '+') { ++i; return factor(); }
        if (s[i] == '(') {
            ++i;
            long long v = expr();
            skip();
            if (i < s.size() && s[i] == ')') ++i;
            return v;
        }
        long long v = 0;
        while (i < s.size() && isdigit((unsigned char)s[i])) v = v * 10 + (s[i++] - '0');
        return v;
    }
    long long term() {
        long long v = factor();
        while (true) {
            skip();
            if (i < s.size() && s[i] == '*')      { ++i; v *= factor(); }
            else if (i < s.size() && s[i] == '/') { ++i; long long d = factor();
                                                   v = (long long)(v / d); }  // toward zero
            else break;
        }
        return v;
    }
    long long expr() {
        long long v = term();
        while (true) {
            skip();
            if (i < s.size() && s[i] == '+')      { ++i; v += term(); }
            else if (i < s.size() && s[i] == '-') { ++i; v -= term(); }
            else break;
        }
        return v;
    }
};

int calculate(const string& s) { return (int)Calculator(s).expr(); }

