def calculate(s: str) -> int:
    """GRAMMAR:
         expr   := term   (('+' | '-') term)*
         term   := factor (('*' | '/') factor)*
         factor := number | '(' expr ')' | '-' factor     <- unary minus lives HERE
    """
    i = 0

    def skip():
        nonlocal i
        while i < len(s) and s[i] == " ":
            i += 1

    def factor():
        nonlocal i
        skip()
        if s[i] == "-":
            i += 1
            return -factor()          # unary minus, right-recursive
        if s[i] == "+":
            i += 1
            return factor()
        if s[i] == "(":
            i += 1
            v = expr()
            skip()
            if i < len(s) and s[i] == ")":
                i += 1
            return v
        v = 0
        while i < len(s) and s[i].isdigit():
            v = v * 10 + int(s[i])
            i += 1
        return v

    def term():
        nonlocal i
        v = factor()
        while True:
            skip()
            if i < len(s) and s[i] == "*":
                i += 1
                v *= factor()
            elif i < len(s) and s[i] == "/":
                i += 1
                d = factor()
                v = int(v / d)        # truncate toward ZERO, matching C++
            else:
                break
        return v

    def expr():
        nonlocal i
        v = term()
        while True:
            skip()
            if i < len(s) and s[i] == "+":
                i += 1
                v += term()
            elif i < len(s) and s[i] == "-":
                i += 1
                v -= term()
            else:
                break
        return v

    return expr()

