// For a 2000x2000 grid, allocating a fresh vector per row is 2000 allocations
// of 8 KB each plus the same in frees. Reusing two buffers makes it TWO
// allocations total. Same asymptotics, very different constant.
int maximalRectangleStreaming(const vector<vector<char>>& grid) {
    if (grid.empty() || grid[0].empty()) return 0;
    int cols = (int)grid[0].size();

    vector<int> heights(cols + 1, 0);   // +1 slot acts as the permanent sentinel
    vector<int> st;                      // index stack, reused every row
    st.reserve(cols + 1);
    int best = 0;

    for (const auto& row : grid) {
        for (int j = 0; j < cols; ++j)
            heights[j] = (row[j] == '1') ? heights[j] + 1 : 0;
        heights[cols] = 0;               // sentinel drains the stack each row

        st.clear();                      // clear() keeps the capacity: no realloc
        for (int i = 0; i <= cols; ++i) {
            while (!st.empty() && heights[st.back()] >= heights[i]) {
                int h = heights[st.back()]; st.pop_back();
                int left = st.empty() ? -1 : st.back();
                best = max(best, h * (i - left - 1));
            }
            st.push_back(i);
        }
    }
    return best;
}
// TIME BUDGET: each row does at most cols pushes and cols pops, so total work is
// 2 * rows * cols = 8 * 10^6 stack operations for a 2000x2000 grid -- milliseconds.
